#include <string.h>

unsigned int calculateChecksum(char *buffer, size_t length) {
    unsigned int sum = 0;
    for (size_t i = 0; i < length; ++i) {
        sum += buffer[i];
    }
    return sum;
}

int main() {
    FILE *inputFile, *outputFile;
    char buffer[4096]; // You can adjust this size as needed
    unsigned int bytesRead = 0;
    unsigned int checksum;

