    if (outputFile == NULL) {
        printf("Error: Unable to create output file.\n");
        fclose(inputFile);
        return 1;
    }

    while ((bytesRead = fread(buffer, sizeof(char), sizeof(buffer), inputFile)) > 0) {
        checksum = calculateChecksum(buffer, bytesRead);
