int scan(char* buffer, size_t maxLength) {
    if (maxLength <= 0 || maxLength > 1024) {
        printf("Error: The maximum length should be between 1 and 1023\n");
        return -1;
    }

    int charsRead = 0;
    char currentChar;

    while (charsRead < maxLength - 1 && (currentChar = getchar()) != '\n' && currentChar != EOF) {
        buffer[charsRead] = currentChar;
        charsRead++;
    }

    if (currentChar == EOF) {
        printf("Error: Unexpected end of file\n");
        return -1;
    } else if (currentChar == '\n') {
        buffer[charsRead] = '\0'; // Null-terminate the string
