#include <sys/types.h>
#include <sys/wait.h>

int main(int argc, char *argv[]) {
    if (argc != 2) {
        printf("Usage: %s username\n", argv[0]);
        return -1;
    }

    pid_t pid = fork();

    if (pid == -1) { // error occurred
        perror("fork");
        return -1;
    } else if (pid == 0) { // child process
        execl("/bin/id", "id", argv[1], NULL);
        perror("execl");
        return -1;
    } else { // parent process, wait for the child to finish
        int status;
        if (waitpid(pid, &status, 0) == -1) {
            perror("waitpid");
            return -1;
        }

        printf("Exit status: %d\n", WEXITSTATUS(status));
        return WEXITSTATUS(status);
    }
}
```

This code will take one argument (username), fork a new process, and run the command "id <username>" in that child process. The exit status of the command is captured and printed in the parent process. If the command fails, an error message will be printed instead.

