#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to escape HTML entities
char* escape_html(const char *input) {
    size_t len = strlen(input);
    char *escaped = malloc(len + 16); // Extra space for replacements and null terminator

    for (size_t i = 0; i < len; ++i) {
        switch (input[i]) {
            case '<': escaped[i] = '&'; escaped[i+1] = 'l'; escaped[i+2] = 't'; escaped[i+3] = ''; break; // less than sign
            case '>': escaped[i] = '&'; escaped[i+1] = 'g'; escaped[i+2] = 't'; escaped[i+3] = ''; break; // greater than sign
            default: escaped[i] = input[i];
        }
    }

    escaped[len] = '\0';
    return escaped;
}

// Function to send a simple "hello [username]" response back to the client
void http_hello_page(FILE *request, FILE *response) {
    char username[256]; // Assuming maximum username length of 255 characters (including null terminator)
    fgets(username, sizeof(username), request); // Read the request up to the newline character
    strtok(username, "\n"); // Remove the newline character

    char response_str[512]; // Assuming a maximum response length of 511 characters (including null terminator)
    snprintf(response_str, sizeof(response_str), "Hello %s\n", escape_html(username));

    fputs(response_str, response); // Write the response to the output stream
}
```

